input.command:
cd assets/fonts
node - <<'EOF'
const fs=require('fs');
const css=fs.readFileSync('latin.css','utf8');
const blocks=css.split('@font-face').slice(1);
let out=''; let n=0;
for(const b of blocks){
  const fam=(b.match(/font-family: '([^']+)'/)||[])[1];
  const style=(b.match(/font-style: (\w+)/)||[])[1];
  const weight=(b.match(/font-weight: (\d+)/)||[])[1];
  const url=(b.match(/url\((https:[^)]+)\)/)||[])[1];
  const ur=(b.match(/unicode-range: ([^;]+)/)||[])[1]||'';
  if(!url) continue;
  // latin basic + latin-ext only (skip cyrillic, vietnamese, greek)
  if(!/U\+0000-00FF/.test(ur) && !/U\+0100-02AF/.test(ur)) continue;
  if(/U\+1E00-1EFF/.test(ur)) continue;
  n++;
  const ext=url.split('.').pop();
  const fname=`${fam.replace(/ /g,'')}-${style}-${weight}-${n}.${ext}`;
  out+=`@font-face{font-family:'${fam}';font-style:${style};font-weight:${weight};font-display:swap;src:url(./${fname}) format('woff2');}\n`;
  fs.writeFileSync(fname, Buffer.from('')); // placeholder path for curl list
  fs.appendFileSync('downloads.txt', url+' '+fname+'\n');
}
fs.writeFileSync('fonts.css',out);
console.log('blocks',n);
EOF
cat downloads.txt | while read url name; do curl -sS "$url" -o "$name"; done
ls -la | head -30; cat fonts.css | head -5

