 *{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101322;color:var(--paper)}body{font-family:var(--body);font-weight:300}button{font:inherit;color:inherit}button:focus-visible,a:focus-visible{outline:2px solid var(--gold);outline-offset:4px}button{cursor:pointer} [hidden]{display:none!important}.game-shell{position:relative;width:100vw;height:100dvh;min-height:500px;overflow:hidden;background:#111522}.title-screen,.story-screen{position:absolute;inset:0;overflow:hidden}.title-screen{background:radial-gradient(ellipse at 68% 34%,#384359 0,#202a3b 23%,#141a29 57%,#101321 85%);isolation:isolate}.title-art{position:absolute;inset:0;background:url('assets/title-art.svg') center 53%/cover no-repeat;opacity:.94;z-index:-2;animation:art-arrive 1.8s var(--ease) both}.title-screen:after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(13,16,27,.88) 0%,rgba(13,16,27,.70) 34%,rgba(13,16,27,.04) 74%),linear-gradient(0deg,rgba(11,14,24,.82),transparent 30%,rgba(12,15,25,.15));pointer-events:none}.title-grain,.scene-grain{position:absolute;inset:0;opacity:.11;pointer-events:none;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E");mix-blend-mode:soft-light}.title-top,.title-bottom{position:absolute;left:5.1%;right:5.1%;display:flex;align-items:center;color:rgba(241,230,202,.72);font-size:10px;letter-spacing:.24em}.title-top{top:5.2%;gap:17px}.seal,.wordmark-seal{display:grid;place-items:center;border:1px solid rgba(219,196,139,.56);color:var(--gold);font-family:'Noto Serif SC',serif}.seal{width:37px;height:37px;font-size:20px}.title-rule{height:1px;width:min(22vw,260px);background:linear-gradient(90deg,var(--line),transparent)}.title-edition{margin-left:auto;font-size:9px;letter-spacing:.19em}.title-lockup{position:absolute;top:21%;left:10.1%;width:min(490px,46vw);animation:fade-up 1.1s .3s both}.title-kicker,.eyebrow,.title-hint,.modal-kicker{font-size:9px;letter-spacing:.28em;color:var(--gold)}.title-lockup h1{font-family:var(--serif);font-weight:400;font-size:clamp(72px,8.2vw,126px);line-height:.76;letter-spacing:-.055em;margin:28px 0 20px;text-shadow:0 6px 42px rgba(0,0,0,.4)}.title-lockup h1 em{font-weight:400;color:#d9bd7a;letter-spacing:-.07em}.title-subtitle{font:italic 400 21px var(--serif);color:rgba(238,228,203,.74);margin:29px 0 34px;letter-spacing:.025em}.begin-button{display:flex;align-items:center;justify-content:space-between;width:226px;padding:14px 15px 14px 19px;border:1px solid rgba(224,202,150,.67);background:rgba(19,23,35,.54);color:#f3e8cc;text-align:left;letter-spacing:.1em;font-size:12px;transition:background .3s,color .3s,transform .3s}.begin-button b{font-size:18px;font-weight:300;color:var(--gold);transition:transform .3s}.begin-button:hover{background:#d7c08b;color:#171923;transform:translateY(-2px)}.begin-button:hover b{transform:translate(3px,-3px);color:#171923}.continue-button{display:block;margin-top:12px;background:none;border:0;color:#d8c99e;font:italic 15px var(--serif);padding:4px 0}.title-hint{margin-top:20px;color:rgba(225,213,183,.48);font-size:8px}.title-bottom{bottom:4.7%;justify-content:space-between;font-size:8px;color:rgba(240,228,197,.45)}.title-settings{position:absolute;right:5%;top:5%;z-index:2}.title-screen .title-top .seal{margin-right:1px}.icon-button{width:35px;height:35px;border:1px solid transparent;background:transparent;color:rgba(241,231,207,.7);font-size:17px;transition:.25s}.icon-button:hover{border-color:var(--line);color:var(--gold);background:rgba(16,19,30,.3)}.title-settings{top:auto;bottom:4%;right:4.6%;opacity:.75}
