### Ran Playwright code
```js
await (async page => {
  const assert = (condition, message) => { if (!condition) throw new Error(message); };
  const progress = () => page.locator('#progress-label').innerText();
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.locator('#begin-button').click();
  assert(await progress() === '01 / 18', 'Story did not begin at scene 1');

  await page.locator('#settings-button').click();
  assert(await page.locator('#modal-title').innerText() === 'Settings', 'Settings did not open');
  await page.locator('#volume').fill('100');
  await page.locator('#settings-done').click();
  await page.locator('#auto-button').click();
  await page.waitForTimeout(2200);
  assert(await progress() === '02 / 18', 'Auto-advance did not move to scene 2');
  await page.locator('#auto-button').click();
  await page.keyboard.press('ArrowLeft');
  assert(await progress() === '01 / 18', 'Left arrow did not go to previous scene');
  await page.keyboard.press('ArrowRight');
  assert(await progress() === '02 / 18', 'Right arrow did not advance');
  await page.locator('#save-button').click();
  await page.locator('#advance-button').click();
  assert(await progress() === '03 / 18', 'Continue did not reach scene 3');
  await page.locator('#load-button').click();
  assert(await progress() === '02 / 18', 'Load did not restore saved scene');

  let choices = 0;
  for (let index = 1; index < 18; index++) {
    const expected = String(index + 1).padStart(2, '0') + ' / 18';
    assert(await progress() === expected, `Unexpected scene before progression: ${await progress()}, expected ${expected}`);
    const options = page.locator('.choice-button');
    if (await options.count()) {
      choices++;
      await options.first().click();
    } else if (index < 17) {
      await page.keyboard.press('Space');
    } else {
      await page.locator('#journal-button').click();
      assert(await page.locator('#modal-title').innerText() === 'Dream journal', 'Journal did not open');
      await page.locator('#journal-done').click();
      await page.locator('#history-button').click();
      assert(await page.locator('#modal-title').innerText() === 'Story so far', 'History did not open');
      await page.locator('#history-done').click();
      await page.locator('#advance-button').click();
      assert(await page.locator('#modal-title').innerText() !== '', 'Ending did not open after final scene');
      break;
    }
  }
  assert(choices === 5, `Expected 5 branching decisions, got ${choices}`);
  assert((await page.locator('#modal-content').innerText()).includes('You have completed'), 'Ending content missing');
  await page.locator('#close-ending').click();
  await page.locator('#prev-button').click();
  await page.locator('#skip-button').click();
  await page.waitForTimeout(250);
  assert(await progress() === '18 / 18', 'Skip-seen did not move to the previously viewed final scene');
  assert(await page.locator('#overlay').isHidden(), 'Skip-seen should not end before the final scene is advanced');
  await page.locator('#skip-button').click();
  await page.locator('#advance-button').click();
  assert((await page.locator('#modal-content').innerText()).includes('You have completed'), 'Final scene did not reach ending');
  return { scenes: 18, branchingChoices: choices, ending: 'passed', autoAdvance: 'passed', saveLoad: 'passed', keyboard: 'passed', journalHistory: 'passed', skipSeen: 'passed' };
})(page);
